package com.franco.desco.adapter.in.web.resourceprogram;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.resourceprogram.*;import com.franco.desco.application.resourceprogram.port.in.ResourceProgramUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/recursos-programados")@Tag(name="Recursos programados",description="Programación, asignación, devolución y disponibilidad de recursos.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class ResourceProgramController{private final ResourceProgramUseCase u;private final ResourceProgramWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public ResourceProgramController(ResourceProgramUseCase u,ResourceProgramWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping@PreAuthorize("@permissionGuard.has(authentication,'RECURSOS_LISTAR')")@Operation(operationId="recursosListar",summary="Listar recursos programados")public ResponseEntity<ApiResponse<PageResponse<ResourceProgramResponses.Summary>>>list(@RequestParam(required=false)String estadoProceso,@RequestParam(required=false)Long campaniaVentaId,@RequestParam(required=false)Long operativoVentaId,@RequestParam(required=false)Long salidaCampoId,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,estadoProceso,campaniaVentaId,operativoVentaId,salidaCampoId),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}")@PreAuthorize("@permissionGuard.has(authentication,'RECURSOS_VER')")@Operation(operationId="recursosVer",summary="Ver recurso programado")public ResponseEntity<ApiResponse<ResourceProgramResponses.Detail>>get(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.get(new ResourceProgramCommands.Get(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @GetMapping("/disponibilidad")@PreAuthorize("@permissionGuard.has(authentication,'RECURSOS_VER')")@Operation(operationId="recursosDisponibilidad",summary="Consultar bienes y suministros disponibles")public ResponseEntity<ApiResponse<ResourceProgramResponses.Availability>>availability(@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.availability(ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'RECURSOS_CREAR')")@Operation(operationId="recursosProgramar",summary="Programar recurso")public ResponseEntity<ApiResponse<ResourceProgramResponses.Created>>program(@Valid@RequestBody ResourceProgramRequests.Program q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.program(new ResourceProgramCommands.Program(q.campaniaVentaId(),q.operativoVentaId(),q.salidaCampoId(),q.bienInventarioId(),q.suministroId(),q.cantidadProgramada(),q.observacion()),ids.resolve(a),meta.resolve(r)),r,ResourceProgramResponses.Created::new);}
 @PutMapping("/{id}")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'RECURSOS_EDITAR')")@Operation(operationId="recursosEditar",summary="Editar recurso programado")public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid@RequestBody ResourceProgramRequests.Update q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.update(new ResourceProgramCommands.Update(id,q.cantidadProgramada(),q.observacion()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/asignar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'RECURSOS_CREAR')")@Operation(operationId="recursosAsignar",summary="Asignar recurso programado")public ResponseEntity<ApiResponse<Void>>assign(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.assign(new ResourceProgramCommands.Assign(id),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/devolucion")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'RECURSOS_CREAR')")@Operation(operationId="recursosRegistrarDevolucion",summary="Registrar devolución de recurso")public ResponseEntity<ApiResponse<Void>>returnResource(@PathVariable Long id,@Valid@RequestBody ResourceProgramRequests.ReturnResource q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.returnResource(new ResourceProgramCommands.ReturnResource(id,q.cantidadDevuelta(),q.observacion()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/consumo")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'RECURSOS_CREAR')")@Operation(operationId="recursosRegistrarConsumo",summary="Registrar consumo pendiente de un suministro asignado")public ResponseEntity<ApiResponse<Void>>consume(@PathVariable Long id,@Valid@RequestBody ResourceProgramRequests.Consume q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.consume(new ResourceProgramCommands.Consume(id,q.cantidadConsumida(),q.observacion()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/cancelar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'RECURSOS_RETIRAR')")@Operation(operationId="recursosCancelar",summary="Cancelar recurso programado")public ResponseEntity<ApiResponse<Void>>cancel(@PathVariable Long id,@Valid@RequestBody ResourceProgramRequests.Cancel q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.cancel(new ResourceProgramCommands.Cancel(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}}
